/*
 * decompress.c
 *
 * Detect the decompression method based on magic number
 */

#include "sys/types.h"
#include "string.h"
#include "stdio.h"
#include "version_autogenerated.h"

#include "decompress.h"
#include "bunzip2.h"
#include "unlzma.h"
#include "unxz.h"
#include "inflate.h"
#include "unlzo.h"
#include "unlz4.h"

error_fn error = NULL;

#ifndef CONFIG_ENABLE_DECOMPRESS_GZIP
# define gunzip NULL
#endif
#ifndef CONFIG_ENABLE_DECOMPRESS_BZIP2
# define bunzip2 NULL
#endif
#ifndef CONFIG_ENABLE_DECOMPRESS_LZMA
# define unlzma NULL
#endif
#ifndef CONFIG_ENABLE_DECOMPRESS_XZ
# define unxz NULL
#endif
#ifndef CONFIG_ENABLE_DECOMPRESS_LZO
# define unlzo NULL
#endif
#ifndef CONFIG_ENABLE_DECOMPRESS_LZ4
# define unlz4 NULL
#endif

struct compress_format {
	unsigned char magic[2];
	const char *name;
	decompress_fn decompressor;
};

static const struct compress_format compressed_formats[] = {
	{ {0x1f, 0x8b}, "gzip", gunzip },
	{ {0x1f, 0x9e}, "gzip", gunzip },
	{ {0x42, 0x5a}, "bzip2", bunzip2 },
	{ {0x5d, 0x00}, "lzma", unlzma },
	{ {0x66, 0x00}, "lzma", unlzma },
	{ {0xfd, 0x37}, "xz", unxz },
	{ {0x89, 0x4c}, "lzo", unlzo },
	{ {0x02, 0x21}, "lz4", unlz4 },
	{ {0, 0}, NULL, NULL }
};

decompress_fn decompress_method(const unsigned char *inbuf, long len,
				const char **name)
{
	const struct compress_format *cf;

	if (len < 2) {
		if (name)
			*name = NULL;
		return NULL;	/* Need at least this much... */
	}

	for (cf = compressed_formats; cf->name; cf++) {
		if (!memcmp(inbuf, cf->magic, 2))
			break;

	}
	if (name)
		*name = cf->name;
	return cf->decompressor;
}

int decompress(unsigned char *inbuf, long len, unsigned char *outbuf, long out_size)
{
	decompress_fn decompress;
	const char *compress_name;
	int res = -1;

	decompress = decompress_method(inbuf, len, &compress_name);

	if (decompress) {
		res = decompress(inbuf, len, NULL, NULL, outbuf, out_size, NULL, NULL);
	} else {
		printf("not support decompressor %s\n", compress_name);
	}

	return res;
}
